primaryQuery:
run: order_items -> {
  aggregate:
    average_lifetime_value is
      sale_price.sum() { where: status != 'Cancelled' and status != 'Returned' }
      / nullif(count(user_id), 0)
}

verifyQuery:
run: order_items -> {
  group_by: user_id
  aggregate: ltv is sale_price.sum() { where: status != 'Cancelled' and status != 'Returned' }
} -> {
  aggregate: average_lifetime_value is ltv.sum() / count()
}
